import type { MetadataRoute } from "next";

/**
 * Web app manifest (served at /manifest.webmanifest). Colours mirror --background in
 * globals.css; the manifest can't read CSS variables, so keep them in sync by hand.
 * Icons are generated by scripts/generate-icons.mjs.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: "Workout Tracker",
    short_name: "Workout",
    description: "Personal exercise library, workout logging, body weight and progress tracking.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: "#18181b",
    theme_color: "#18181b",
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      {
        src: "/icons/icon-maskable-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "maskable",
      },
      {
        src: "/icons/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
